        // Public repos download from the browser URL; private repos return 404/HTML there
        // and must be fetched from the API asset endpoint instead.
        let download_url = select_github_download_url(pkg.private, &url, url_api.as_deref()).await;
        self.download(ctx, &tv, &download_url, &filename).await?;

        // Snapshot before any mutation so verify() knows whether the lockfile
        // originally contained a checksum (vs. one we just wrote from api_digest).
        let lockfile_has_checksum = tv
            .lock_platforms
            .get(&platform_key)
            .is_some_and(|p| p.checksum.is_some());

        if validated_url.is_none() {
            let platform_info = tv.lock_platforms.entry(platform_key).or_default();
            platform_info.url = Some(url.clone());
            platform_info.url_api = url_api.clone();
            if let Some(digest) = api_digest.clone()
                && !lockfile_has_checksum
            {
                debug!("using GitHub API digest for checksum verification");
                platform_info.checksum = Some(digest);
            }
            None
        };
        Some(
            target
                .libc()
                .map(str::to_string)
                .or(settings_libc)
                .unwrap_or_else(|| "gnu".to_string()),
        )
    }

    fn apply_aqua_libc_replacement(
        mut pkg: AquaPackage,
        target_os: &str,
        libc: Option<String>,
    ) -> AquaPackage {
        let Some(libc) = libc else {
            return pkg;
        };
        if target_os != "linux" {
            return pkg;
        }
        let Some(linux) = pkg.replacements.get_mut("linux") else {
            return pkg;
        };
        if is_aqua_linux_libc_replacement(linux) {
            let libc = if libc == "musl" { "musl" } else { "gnu" };
            let prefix = linux
                .strip_suffix("-gnu")
                .or_else(|| linux.strip_suffix("-musl"))
                .unwrap_or("unknown-linux");
            *linux = format!("{prefix}-{libc}");
        }
        pkg
    }

    fn apply_selected_asset_libc_replacement(
        pkg: AquaPackage,
        target_os: &str,
        filename: &str,
    ) -> AquaPackage {
        let tokens = asset_name_tokens(filename);
        let libc = if tokens.iter().any(|token| token == "musl") {
            Some("musl")
        } else if tokens
            .iter()
            .any(|token| matches!(token.as_str(), "gnu" | "glibc"))
        {
            Some("gnu")
        } else {
            None
        };
        Self::apply_aqua_libc_replacement(pkg, target_os, libc.map(str::to_string))
    }

